/* AP Psychology Course and Exam Description (2024-25 onward), Unit 4, Social Psychology and Personality, topics 4.1–4.7 (numbering of 4.4–4.7 as recalled by the author; see the build report).
   https://apcentral.collegeboard.org/courses/ap-psychology/course
   Original wording; every study, dataset and participant described as fictional is invented for practice. Classic studies (Festinger and Carlsmith, Asch, Milgram,
   Zimbardo, Darley and Latané, Sherif, Freud, Maslow, Rogers, Bandura, Mischel, Schachter and Singer) are summarized with their ethical and replication critiques and approximate figures are labelled.
   No group is described by a stereotype. Pictures are drawn in code from the stated numbers. */
const fig=(title,o)=>({t:'figure',title,dots:'',...o,hide:Object.keys(o.pts||{}).join('')});
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{}),box:true});
const bars=(title,labels,values)=>({t:'chart',kind:'bars',title,bars:labels.map((label,i)=>({label,value:values[i]}))});
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const scenario=(title,p)=>{const lines=[];let line='';for(const word of p.split(' ')){if((line+' '+word).length>49){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return {t:'board',title,lines};};
const rnd=n=>Math.round(n*1e4)/1e4;
/* dia: boxes placed in pixel units (x right, y up, the picture is 552 wide); links are arrows from one box edge to another; extra holds raw pts, segs and notes */
const dia=(title,nodes,links,extra={},h=192)=>{const pts={},polys=[],segs=[],notes=[];
 nodes.forEach((n,i)=>{Object.assign(pts,{['A'+i]:[n.x,n.y],['B'+i]:[n.x+n.w,n.y],['C'+i]:[n.x+n.w,n.y+n.h],['D'+i]:[n.x,n.y+n.h]});polys.push({v:`A${i}B${i}C${i}D${i}`,col:n.col??i%4});
  const L=n.text.split('|'),cx=n.x+n.w/2,cy=n.y+n.h/2;L.forEach((t,k)=>notes.push({at:[cx,cy+(L.length-1)*7.5-k*15],text:t}));});
 const edge=(n,dx,dy)=>{const t=Math.min(dx?n.w/2/Math.abs(dx):1e9,dy?n.h/2/Math.abs(dy):1e9);return [n.x+n.w/2+dx*t,n.y+n.h/2+dy*t];};
 links.forEach(([a,b],k)=>{const A=nodes[a],B=nodes[b],dx=B.x+B.w/2-A.x-A.w/2,dy=B.y+B.h/2-A.y-A.h/2,p=edge(A,dx,dy),q=edge(B,-dx,-dy),g=4/Math.hypot(dx,dy);
  pts['E'+k]=[p[0]+dx*g,p[1]+dy*g];pts['F'+k]=[q[0]-dx*g,q[1]-dy*g];segs.push({v:`E${k}F${k}`,arrows:1,col:1});});
 Object.assign(pts,extra.pts||{});segs.push(...(extra.segs||[]));notes.push(...(extra.notes||[]));
 return fig(title,{pts,polys,segs,notes,view:[0,552,0,h]});};
const CAUSES=dia('Two kinds of explanation for the same behavior',[{x:200,y:124,w:152,h:44,text:'A driver cuts you off|the behavior seen',col:2},{x:0,y:28,w:220,h:50,text:'Dispositional (internal)|trait, motive, character',col:0},{x:332,y:28,w:220,h:50,text:'Situational (external)|rush, rules, an emergency',col:1}],[[0,1],[0,2]]);
const ACTOR=bars('Fictional lateness study: percent blaming the situation',['Own lateness','A friend\'s lateness'],[60,25]);
const ELM=dia('Elaboration likelihood model of persuasion',[{x:0,y:76,w:140,h:44,text:'Persuasive|message',col:2},{x:210,y:124,w:170,h:44,text:'Central route|weighs the arguments',col:0},{x:210,y:28,w:170,h:44,text:'Peripheral route|reacts to cues, fame',col:1},{x:430,y:124,w:122,h:44,text:'Longer-lasting|change',col:3},{x:430,y:28,w:122,h:44,text:'Often fades|sooner',col:3}],[[0,1],[0,2],[1,3],[2,4]]);
const DISS=dia('Cognitive dissonance reduced by changing an attitude',[{x:0,y:76,w:150,h:50,text:'Say a dull task|is fun for $1',col:0},{x:200,y:76,w:150,h:50,text:'Dissonance|clash of belief, act',col:1},{x:400,y:76,w:150,h:50,text:'Attitude shifts|task seems fun',col:2}],[[0,1],[1,2]],{notes:[{at:[276,28],text:'little outside justification means more pressure to change the attitude'}]});
const CONFORM=bars('Fictional conformity study: percent of critical responses matching a wrong group',['Judging alone','Facing a unanimous group'],[2,30]);
const OBEY=bars('Fictional obedience variants: percent who obeyed fully',['Experimenter in the room','Orders given by phone'],[70,25]);
const GROUPS=board('Behavior in groups: names to know',['Social facilitation: others watching help easy tasks','Social loafing: less effort when work is shared','Deindividuation: lost self-awareness in a crowd','Group polarization: discussion strengthens a lean','Groupthink: harmony outranks critical thinking','Stanford prison study: strong critiques apply']);
const HELP=bars('Fictional helping study: percent who helped',['Alone','Believed others present'],[80,40]);
const FREUD=dia('Freud\'s three parts of personality',[{x:0,y:104,w:160,h:52,text:'Id|wants it now (pleasure)',col:0},{x:196,y:104,w:160,h:52,text:'Ego|mediates (reality)',col:1},{x:392,y:104,w:160,h:52,text:'Superego|conscience (ideals)',col:2}],[[0,1],[2,1]],{notes:[{at:[276,52],text:'psychosexual stages: oral, anal, phallic, latency, genital'},{at:[276,24],text:'historically important; many claims are hard to test and have limited support'}]});
const SELF=bars('Fictional self-ratings added across 4 items (1-10 scale)',['Real self','Ideal self'],[14,32]);
const BIG5=bars('Fictional Big Five percentiles for one person',['Openness','Conscientiousness','Extraversion','Agreeableness','Neuroticism'],[70,85,35,60,20]);
const CONSC=(()=>({t:'chart',kind:'scatter',title:'Fictional sample: conscientiousness score and weekly study hours',x:[0,10],y:[0,10],points:[[1,2],[2,3],[3,3],[4,5],[5,4],[6,6],[7,7],[8,7],[9,9],[10,8]],xlabel:'conscientiousness score',ylabel:'study hours'}))();
const AROUSAL=(()=>{const pts=[];for(let x=0;x<=10;x++)pts.push([x,100-4*(x-5)**2]);return {t:'plot',title:'Schematic Yerkes-Dodson curve (moderately difficult task)',x:[0,10],y:[0,100],paths:[{pts,label:'performance'}],vlines:[{x:5,label:'moderate arousal',dash:true}]};})();
const DRAW=bars('Fictional free-time drawing (minutes)',['Before prizes','After prizes ended'],[25,10]);
const THEORIES=dia('Two theories of emotion',[{x:0,y:124,w:150,h:44,text:'Event|snake on the path',col:0},{x:200,y:124,w:150,h:44,text:'Body arousal|racing heart',col:1},{x:400,y:124,w:150,h:44,text:'Feeling|fear',col:2},{x:0,y:30,w:150,h:44,text:'Arousal|heart pounding',col:1},{x:200,y:30,w:150,h:44,text:'Label it|"I am excited"',col:3},{x:400,y:30,w:150,h:44,text:'Emotion|named by context',col:2}],[[0,1],[1,2],[3,4],[4,5]],{notes:[{at:[276,181],text:'James-Lange: the body responds first'},{at:[276,92],text:'Schachter-Singer: arousal plus the label we give it'}]});
const POLY=bars('Fictional polygraph screen of 100 truthful people',['Not flagged','Wrongly flagged'],[80,20]);
const WRAP=board('Social psychology and personality checklist',['Attribution: person or situation, and our biases','Attitudes: components, routes, dissonance','Social situations: weigh the study and its critiques','Personality: theory, evidence and its limits','Motivation: need, arousal, incentive, goals','Emotion: body, thought and a cautious look at lie detection']);
const TRY=[
 'Try it: in a fictional study, a researcher coded 80 written explanations of a stranger\'s late arrival and 52 named a trait of the stranger as the cause. What percent of the explanations were dispositional? Give the number without a percent sign.',
 'Try it: in a fictional obedience study, 45 participants were told to continue giving what they believed were increasing shocks (no shocks were real), and 27 continued to the highest level. What percent obeyed fully? Give the number without a percent sign.',
 'Try it: a fictional 5-item extraversion scale uses ratings from 1 (disagree strongly) to 5 (agree strongly). Items 2 and 5 are reverse-scored (a rating x counts as 6 minus x). A person\'s ratings for items 1 to 5 are 5, 3, 2, 4, 1. What is the total score?'
];
